contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        deployer = msg.sender;
    }

    // single public test function
    function run(address caller, uint sendAmount) public payable {
        require(address(this).balance >= sendAmount);
        // record owner and balance before
        address ownerBefore = c.Owner();
        uint balanceBefore = address(c).balance;

        // Try withdraw as non-owner: simulate by calling from this contract (which is not Owner unless deployer matches)
        bool revertedNonOwner;
        // If this contract happens to be the owner, then the non-owner test isn't meaningful; require caller param to differ
        // But we cannot change msg.sender when calling c from here; the InvMutTest contract is the caller for all c calls.
        // So we use the provided caller parameter: if caller == ownerBefore then we attempt owner-path by first making Owner the caller via Command (owner only) cannot be done.
        // Instead, we assert property that when msg.sender != Owner, withdraw reverts. Our caller is this contract; check that.
        if (address(this) != ownerBefore) {
            try c.withdraw{value: 0}() {
                revertedNonOwner = false;
            } catch {
                revertedNonOwner = true;
            }
        } else {
            // If this contract is the owner, we cannot test non-owner behavior; set revertedNonOwner = true to avoid weakening assertion
            revertedNonOwner = true;
        }

        // Now perform a withdraw as the (apparent) owner by calling Command to force change of Owner is impossible; so we only check behavior when this contract is owner: after withdraw, balance should be zero
        bool ownerIsThis = (address(this) == ownerBefore);
        bool withdrewReverted;
        if (ownerIsThis) {
            // send some ether into c so withdraw will transfer something
            // first send Ether to c using receive fallback by calling multiplicate with value less than or equal to balance to avoid transfer
            // Simpler: directly send value via Command can't since only owner can call payable functions with value to change balance. But this contract is owner, so can send.
            // send sendAmount to contract c by calling multiplicate with value sendAmount
            try c.multiplicate{value: sendAmount}(address(this)) {
                // ignore
            } catch {
                // ignore
            }

            // attempt withdraw as owner
            try c.withdraw{value: 0}() {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        } else {
            withdrewReverted = true;
        }

        uint balanceAfter = address(c).balance;
        address ownerAfter = c.Owner();

        // General rule (single assert):
        // - If this contract is not Owner, withdraw must revert (revertedNonOwner == true).
        // - If this contract is Owner and withdraw did not revert, then contract balance becomes zero and Owner unchanged.
        assert(
            (address(this) != ownerBefore && revertedNonOwner)
            || (ownerIsThis && !withdrewReverted && balanceAfter == 0 && ownerAfter == ownerBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // Observe owner and balance before any interactions
        address ownerBefore = c.Owner();
        uint balanceBefore = address(c).balance;

        // Ensure some ether is in c if this contract is the owner and sendAmount > 0
        // We perform the deposit by calling multiplicate which is payable and may transfer out depending on its logic.
        // This call must be top-level. We ignore whether it reverts; if it reverts the following logic still holds because balances won't have increased.
        bool depositReverted;
        try c.multiplicate{value: sendAmount}(address(this)) {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // Attempt withdraw and record whether it reverted
        bool withdrawReverted;
        try c.withdraw{value: 0}() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Observe owner and balance after the withdraw attempt
        address ownerAfter = c.Owner();
        uint balanceAfter = address(c).balance;

        // General rule (single assert):
        // - If this contract was not the owner before, withdraw must revert.
        // - If this contract was the owner before and withdraw did not revert, then Owner remains the same and the contract's balance becomes zero.
        assert(
            (address(this) != ownerBefore && withdrawReverted)
            || (address(this) == ownerBefore && (!withdrawReverted ==> (ownerAfter == ownerBefore && balanceAfter == 0)))
        );
    }

    // Helper to allow using implication in assert expression: a ==> b is (!a || b)
    // But solidity doesn't have custom operators; we emulate implication by replacing (A ==> B) with (!A || B) inside the assert above.

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address payable recipient, uint amount) public payable {
        require(address(this).balance >= amount);

        // read balance before
        uint balBefore = address(c).balance;

        // call multiplicate with provided amount of ETH
        bool reverted;
        try c.multiplicate{value: amount}(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balance after
        uint balAfter = address(c).balance;

        // If call did not revert and the if-branch in multiplicate triggers, then the whole contract balance
        // plus msg.value must have been transferred to recipient, so c balance becomes zero.
        // We cannot directly observe transfers to recipient, but we can assert that whenever the call succeeded
        // AND the condition msg.value >= balBefore held (so the branch should execute), then c's balance is zero afterwards.
        assert(reverted || (amount < balBefore) || balAfter == 0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: target address to call, arbitrary calldata, and ETH to forward with the call
    function run(address target, bytes memory data, uint value) public payable {
        // ensure this contract has enough ETH to forward
        require(address(this).balance >= value);

        // read owner and balance before
        address ownerBefore = c.Owner();
        uint balBefore = address(c).balance;

        // Call Command forwarding `value` wei, catch revert
        bool reverted;
        try c.Command{value: value}(target, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read owner and balance after
        address ownerAfter = c.Owner();
        uint balAfter = address(c).balance;

        // General rule asserted for all inputs:
        // If the call did not revert then the caller must have been Owner (i.e. c.Owner was this contract)
        // and the Owner did not change, and the contract's balance did not increase due to the call.
        // We cannot assert that balance decreased (the target might have sent back ETH), only that it did not grow.
        assert(reverted || (ownerBefore == address(this) && ownerAfter == ownerBefore && balAfter <= balBefore));
    }

    // allow receiving ETH when the test forwards value to c or receives refunds
    receive() external payable {}
}

