contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: target address and calldata to forward, plus ether forwarded
    function run(address target, bytes memory data, uint value) public payable {
        // ensure this contract has enough ETH to forward into Command
        require(address(this).balance >= value);

        // read observables before
        address ownerBefore = c.Owner();
        uint balBefore = address(c).balance;

        // We want to test behavior when InvMutTest is NOT the Owner of c.
        // The constructor of the fresh c sets Owner = msg.sender (the deployer),
        // which is the external account that deployed c, not this test contract.
        // However to be safe we require ownerBefore != address(this)
        require(ownerBefore != address(this));

        // call Command and catch revert
        bool reverted;
        try c.Command{value: value}(target, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observables after
        address ownerAfter = c.Owner();
        uint balAfter = address(c).balance;

        // General rule: if someone who is NOT Owner calls Command, then either it reverts,
        // or (if it did not revert) Owner must remain unchanged and C's balance must not increase.
        assert(reverted || (ownerAfter == ownerBefore && balAfter <= balBefore));
    }

    // allow receiving ETH when forwarding
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test: ownerForwardTarget is called by the Owner of c, forwarding value to target with data.
    // Params: target address, calldata, and amount of ETH to forward from this contract into c.Command.
    function run(address target, bytes memory data, uint amount) public payable {
        // ensure this test contract has enough ETH to forward into c.Command
        require(address(this).balance >= amount);

        // read observables before
        address ownerBefore = c.Owner();
        uint balBefore = address(c).balance;

        // We need to call as Owner. The freshly deployed c set Owner = deployer of c (external account).
        // The checker deploys c and then deploys this InvMutTest passing c, so normally ownerBefore != address(this).
        // To exercise the Owner-call path we require that ownerBefore == address(this), and if not the property still must hold
        // for the case when this contract is Owner; otherwise we will early-return by making a precondition requiring ownership.
        require(ownerBefore == address(this));

        // perform the call as Owner, capture whether it reverts
        bool reverted;
        try c.Command{value: amount}(target, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observables after
        address ownerAfter = c.Owner();
        uint balAfter = address(c).balance;

        // If the Owner successfully calls Command (i.e., did not revert), then Owner must stay the same
        // and c's balance must not have increased (any forwarded ETH should not be kept by c).
        assert(reverted || (ownerAfter == ownerBefore && balAfter <= balBefore));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test property of Command(address,bytes) when called from this contract.
    // Parameters:
    // - adr: target address to forward the call to
    // - data: calldata to send
    // - amount: ether amount to forward with the call
    function run(address adr, bytes calldata data, uint256 amount) public payable {
        // ensure this contract has enough balance to forward 'amount'
        require(address(this).balance >= amount);

        // Observe pre-call values
        address owner_before = c.Owner();
        uint256 bal_before = address(c).balance;

        // Perform the call and capture whether it reverted
        bool reverted;
        try c.Command{value: amount}(adr, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-call values
        address owner_after = c.Owner();
        uint256 bal_after = address(c).balance;

        // If Command succeeded then caller must have been Owner (require in C),
        // and Owner should remain unchanged, and c's balance should be decreased by at most amount.
        // Note: adr.call may forward less or zero if the call fails internally but Command would then not revert.
        // We assert a general relation: if not reverted, owner stayed same and bal_after <= bal_before and
        // bal_before - bal_after <= amount
        assert(
            reverted || (
                owner_after == owner_before
                && bal_after <= bal_before
                && (bal_before - bal_after) <= amount
            )
        );
    }

    // allow this test contract to receive ether so it can forward to c
    receive() external payable {}
}

contract InvMutTest {
