    // Test multiplicate(adr) with forwarded Ether amount 'amount'.
    // Parameters:
    // - adr: recipient address passed to multiplicate
    // - amount: Ether forwarded to multiplicate
    function run(address payable adr, uint256 amount) public payable {
        // ensure this contract has enough balance to forward 'amount'
        require(address(this).balance >= amount);

        // Observe pre-call values
        address owner_before = c.Owner();
        uint256 bal_before = address(c).balance;

        // Call multiplicate and capture whether it reverted
        bool reverted;
        try c.multiplicate{value: amount}(adr) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-call values
        address owner_after = c.Owner();
        uint256 bal_after = address(c).balance;

        // If call did not revert and the require condition in multiplicate (msg.value >= balance) held
        // then multiplicate should transfer the whole (old balance + msg.value) out, leaving c.balance == 0
        // and Owner must remain unchanged (multiplicate does not modify Owner).
        // We assert: either it reverted, or if amount >= bal_before then owner unchanged and bal_after == 0.
        assert(
            reverted || (amount < bal_before) || (owner_after == owner_before && bal_after == 0)
        );
    }

    // allow this test contract to receive ether so it can forward to c
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Parameters:
    // - target: address passed to Command
    // - data: calldata passed to Command
    // - amount: wei forwarded to Command
    function run(address target, bytes calldata data, uint256 amount) public payable {
        // ensure this contract can forward `amount`
        require(address(this).balance >= amount);

        // Observe pre-call values
        address owner_before = c.Owner();
        uint256 bal_before = address(c).balance;

        // Ensure the test contract is NOT the Owner: if it is Owner, this rule would be different.
        // We encode this as a runtime precondition so the checker only considers cases where
        // this contract is not Owner.
        require(owner_before != address(this));

        // Call Command and record whether it reverted
        bool reverted;
        try c.Command{value: amount}(target, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-call values
        address owner_after = c.Owner();
        uint256 bal_after = address(c).balance;

        // General rule:
        // If the call did not revert then Owner must remain unchanged (non-owners cannot change Owner),
        // and the new balance must be either the same as before (if the forwarded value was not accepted
        // by any internal call) or decreased by at most the forwarded amount (i.e., bal_after >= bal_before - amount)
        // and also bal_after <= bal_before (since Command cannot increase contract balance except by msg.value,
        // but msg.value is forwarded so balance should not exceed bal_before + amount; however from caller perspective
        // we allow that at most the forwarded amount may be consumed). To keep the assertion purely observational
        // and safe from underflow, we assert: if not reverted then owner unchanged and bal_after + amount >= bal_before.

        assert(reverted || (owner_after == owner_before && bal_after + amount >= bal_before));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // - target: address to pass as adr to multiplicate
    // - amount: wei forwarded to multiplicate
    function run(address target, uint256 amount) public payable {
        // allow forwarding `amount`
        require(address(this).balance >= amount);

        // Observe pre-call public values
        address owner_before = c.Owner();
        uint256 bal_before = address(c).balance;

        // We specifically test the case amount < bal_before. If bal_before == 0 then the inequality cannot hold
        // so require it to focus the checker on meaningful cases.
        require(bal_before > amount);

        // Call multiplicate and record whether it reverted
        bool reverted;
        try c.multiplicate{value: amount}(target) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-call public values
        address owner_after = c.Owner();
        uint256 bal_after = address(c).balance;

        // General rule: when amount < previous balance, multiplicate's branch that transfers should not trigger,
        // so the call must not revert and it must not change Owner or c.balance.
        assert(!reverted && owner_after == owner_before && bal_after == bal_before);
    }

    receive() external payable {}
}
